import React from "react";
import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";

const Cart = () => {
    const { cart, addToCart, removeFromCart, updateQuantity, totalItems, totalPrice, setOrders } = useCart();
    const navigate = useNavigate();

    // Handle placing order and transferring cart items to orders
    const handlePlaceOrder = () => {
        const order = {
            id: new Date().getTime(), // Generate a unique order ID
            items: cart,
            date: new Date().toLocaleDateString(),
        };
        setOrders((prevOrders) => [...prevOrders, order]); // Add the order to the orders state
        alert("Đặt hàng thành công!");
        navigate("/orderlist"); // Navigate to the order list page
    };

    return (
        <div className="container m-auto mt-4 mb-4">
            {/* Cart items */}
            <div className="row">
                <div className="col-md-8">
                    <h2>Giỏ Hàng</h2>
                    <div className="cart-items">
                        {cart.length === 0 ? (
                            <p>Giỏ hàng của bạn trống.</p>
                        ) : (
                            cart.map((product) => (
                                <div key={product.id} className="cart-item d-flex align-items-center">
                                    <img
                                        src={product.image}
                                        alt={product.name}
                                        className="product-image"
                                        style={{ width: "100px", height: "100px" }}
                                    />
                                    <div className="cart-item-details mx-3">
                                        <h5>{product.name}</h5>
                                        <p>{product.description}</p>
                                        <div className="d-flex align-items-center">
                                            <button
                                                className="btn btn-secondary mx-2"
                                                onClick={() => updateQuantity(product.id, "decrease")}
                                            >
                                                -
                                            </button>
                                            <span>{product.quantity}</span>
                                            <button
                                                className="btn btn-secondary mx-2"
                                                onClick={() => updateQuantity(product.id, "increase")}
                                            >
                                                +
                                            </button>
                                        </div>
                                        <p className="price mt-2">Giá: {product.price} VND</p>
                                    </div>
                                    <button
                                        className="btn btn-danger"
                                        onClick={() => removeFromCart(product.id)}
                                    >
                                        Xóa
                                    </button>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Checkout section */}
                <div className="col-md-4">
                    <h3>Thông Tin Thanh Toán</h3>
                    <div className="cart-summary">
                        <p>Tổng Số Lượng: {totalItems}</p>
                        <p>Tổng Tiền: {totalPrice} VND</p>
                        <button className="btn btn-success w-100" onClick={handlePlaceOrder}>
                            Thanh Toán
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Cart;
